<?php
require_once __DIR__ . '/../includes/init.php'; requireAdmin();
$filters=['item_id'=>(string)($_GET['item_id']??''),'category'=>(string)($_GET['category']??''),'movement_type'=>(string)($_GET['movement_type']??''),'start_date'=>(string)($_GET['start_date']??''),'end_date'=>(string)($_GET['end_date']??'')];$rows=historyRows($filters);$in=0;$out=0;foreach($rows as $r){if($r['movement_type']==='IN')$in+=(int)$r['quantity'];else$out+=(int)$r['quantity'];}$title='Reports';$active='reports';$items=allItems();$categories=itemCategories();layoutStart($title,$active);
?><div class="page-heading no-print"><div><div class="eyebrow">ANALYTICS</div><h1>Stock movement report</h1><p>Review inventory movements across a selected period.</p></div><button class="button primary" type="button" onclick="window.print()">⎙ Print report</button></div><section class="panel report-filter no-print"><form class="filter-bar wrap" method="get"><select name="item_id"><option value="">All items</option><?php foreach($items as $i):?><option value="<?= e($i['id']) ?>" <?= (string)$i['id']===$filters['item_id']?'selected':'' ?>><?= e($i['item_code'].' · '.$i['item_name']) ?></option><?php endforeach;?></select><select name="category"><option value="">All categories</option><?php foreach($categories as $c):?><option value="<?= e($c) ?>" <?= $filters['category']===$c?'selected':'' ?>><?= e($c) ?></option><?php endforeach;?></select><select name="movement_type"><option value="">All types</option><option value="IN" <?= $filters['movement_type']==='IN'?'selected':'' ?>>IN</option><option value="OUT" <?= $filters['movement_type']==='OUT'?'selected':'' ?>>OUT</option></select><label class="date-filter">From<input type="date" name="start_date" value="<?= e($filters['start_date']) ?>"></label><label class="date-filter">To<input type="date" name="end_date" value="<?= e($filters['end_date']) ?>"></label><button class="button primary">Generate report</button><a class="text-link" href="<?= e(url('admin/reports.php')) ?>">Reset</a></form></section><div class="print-heading"><h1><?= e(APP_NAME) ?> · Stock movement report</h1><p>Generated <?= e(date('M j, Y')) ?><?= $filters['start_date']||$filters['end_date']?' · Period '.e($filters['start_date']?:'Beginning').' to '.e($filters['end_date']?:'Today'):'' ?></p></div><section class="stats-grid three"><article class="stat-card"><span class="stat-icon green">↓</span><span class="stat-label">Total stock IN</span><strong><?= number_format($in) ?></strong><span class="stat-note">Units received</span></article><article class="stat-card"><span class="stat-icon red">↑</span><span class="stat-label">Total stock OUT</span><strong><?= number_format($out) ?></strong><span class="stat-note">Units dispatched</span></article><article class="stat-card"><span class="stat-icon blue">↔</span><span class="stat-label">Net movement</span><strong><?= number_format($in-$out) ?></strong><span class="stat-note">IN minus OUT</span></article></section><section class="panel"><div class="panel-heading"><div><h2>Detailed movements</h2><p><?= count($rows) ?> records</p></div></div><div class="table-wrap"><table><thead><tr><th>Date</th><th>Item code</th><th>Item name</th><th>Category</th><th>IN</th><th>OUT</th><th>Reference</th><th>User</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="8" class="empty">No movements found for this report.</td></tr><?php else:foreach($rows as $r):?><tr><td><?= e(dateValue($r['movement_date'])) ?></td><td><?= e($r['item_code']) ?></td><td><?= e($r['item_name']) ?></td><td><?= e($r['category']) ?></td><td class="in-text"><?= $r['movement_type']==='IN'?'+'.e($r['quantity']):'—' ?></td><td class="out-text"><?= $r['movement_type']==='OUT'?'−'.e($r['quantity']):'—' ?></td><td><?= e($r['reference_note']?:'—') ?></td><td><?= e($r['full_name']) ?></td></tr><?php endforeach;endif;?></tbody></table></div></section><?php layoutEnd(); ?>
